// Parse the JSON response from OpenAI if returned as a string
let aiResponse = {};
try {
  const messageContent = $json.choices[0].message.content;
  aiResponse = typeof messageContent === 'string' ? JSON.parse(messageContent) : messageContent;
} catch (e) {
  throw new Error("Failed to parse OpenAI structured JSON output: " + e.message);
}

return {
  ...aiResponse
};

// Retrieve items from prior steps
const aiData = $('Parse AI Output').item.json;
const unsplashData = $('Search Cover Image (Unsplash)').item.json;
const genresList = $('Fetch Supabase Genres').items.map(item => item.json);

// Get Unsplash regular image URL with a fallback cover
let coverUrl = 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?q=80&w=600';
try {
  if (unsplashData.results && unsplashData.results.length > 0) {
    coverUrl = unsplashData.results[0].urls.regular;
  }
} catch (e) {
  // Keep default cover URL
}

// Match genre to ID
const matchedGenre = genresList.find(
  g => g.name.toLowerCase() === aiData.genre_name.toLowerCase()
) || genresList[0];

return {
  title: aiData.title,
  slug: aiData.slug,
  description: aiData.description,
  author: aiData.author,
  genre_id: matchedGenre ? matchedGenre.id : null,
  status: aiData.status || 'ongoing',
  is_published: true,
  cover_url: coverUrl,
  meta_title: aiData.meta_title,
  meta_description: aiData.meta_description
};
